#include <commdlg.h>    // GetOpenFileName: pick a custom folder thumbnail
// This SDK's shellapi.h gates SHDefExtractIcon behind IE/NTDDI macros and
// never declares it: the prototype (shell32 export) is added here. It
// extracts the icon at a REQUESTED size - up to 256px from the exe/dll -
// which is the HD source for big grid cells (Round 13).
