// Which palette is live: 0 Midnight (default), 1 Dark, 2 Light.  The
// index persists on its own settings line ("palette"); a missing line
// (older files) simply keeps the default.
enum { PAL_MID_I = 0, PAL_DARK_I = 1, PAL_LIGHT_I = 2, PAL_COUNT_N = 3 };
static int g_pal_idx = 0;
static const Palette* P = &PAL_MIDNIGHT;

static const char* pal_name(int i) {
    return i == PAL_LIGHT_I ? "Light"
         : i == PAL_DARK_I  ? "Dark"
         :                    "Midnight";
}
static const Palette* pal_at(int i) {
    return i == PAL_LIGHT_I ? &PAL_LIGHT
         : i == PAL_DARK_I  ? &PAL_DARK
         :                    &PAL_MIDNIGHT;
}
static void pal_apply(void) { P = pal_at(g_pal_idx); }

// ------------------------------------------------------------
// Caches: Windows shell thumbnails + icons
// (The old IPicture cache is gone: full-size image decodes moved to the
// worker thread, see the async pipeline below.)
// ------------------------------------------------------------
typedef struct {
    bool used;
    bool pending;          // not resolved yet - queue/await the worker
    bool queued;           // an icon job for THIS entry is on the worker
                           // (checked before queueing, cleared on drain,
                           //  reset by every fresh entry's memset in
                           //  icon_for()/icons_clear())
    char path[1024];
    HICON icon;
    HBITMAP bmp32;         // the icon's own bitmap (captured once, used
                           // to draw BIG cells smoothly instead of the
                           // blocky nearest-neighbour DrawIconEx stretch)
    HBITMAP bmpBig;        // 256px (jumbo) copy from the Windows system
                           // image list - the crisp source for ANY cell
                           // size; bmp32 stays the 32px fallback
    unsigned char big_state; // 0 = not tried yet, 1 = HD ok, 2 = no HD
    unsigned int stamp;
    unsigned char tries;   // failed attempts (retried, not cached forever)
    unsigned int retry_at; // frame of the next allowed attempt
} IconEnt;

static IconEnt g_icons[ICON_CACHE];
static unsigned int g_icon_stamp = 1;
static bool g_ole_ready = false;

// Shell lookups are SLOW (they can decode a video frame or scan a folder).
// Asking for 30 of them inside one paint is what froze the window, so each
// frame gets a budget: the rest keep their drawn/old fallback and are
// retried on the next frame (state "pending").
#define ICONS_PER_FRAME 512        // hard caps ... per FRAME the shell work
#define THUMBS_PER_FRAME 32        // gets at most these many calls
#define FRAME_SHELL_MS 10          // ... and never more than this many ms
// Round 14 "10x fast load": while a folder is STILL FILLING IN (a
// navigation happened or a frame ran out of time = queued shell work)
// raise the per-frame time cap to 35ms so ~3x more lookups land per
// frame, then decay after 90 idle frames. The burst is skipped while the
// zoom is easing so the animation stays smooth; idle stays at 10ms.
#define SHELL_BURST_MS 35
#define SHELL_BURST_FRAMES 90
static int g_icon_budget = ICONS_PER_FRAME;
static int g_tbmp_budget = THUMBS_PER_FRAME;
static DWORD g_shell_deadline = 0xFFFFFFFFu;  // no limit before the 1st paint
static bool g_shell_unlimited = false;        // selftest: never throttled
static int g_shell_burst = 0;                 // catch-up frames left
static DWORD g_nav_tick = 0;                  // last load_dir, for LOAD logs
// TRUE while a visible item still has no shell icon: paint() then runs the
