static int    g_ctx_tab = -1;             // right-clicked TAB index (tab menu)
// The sidebar menu acts on a SNAPSHOT: the sidebar rebuilds itself
// (recents come and go, bookmarks change) while its menu is open.
static char   g_ctx_side_path[1024];
