// ---- multi-selection ----
// g_app.selected stays the PRIMARY row (the last one clicked); g_sel[] is
// the whole set the operations act on. Ctrl+click toggles a row, Shift+
// click takes the range, Ctrl+A takes everything.  (SEL_MAX lives above
// FolderView - the per-pane stored copy needs it too.)
static int g_sel[SEL_MAX];
static int g_sel_n;

static void sel_clear(void) { g_sel_n = 0; }
static bool sel_contains(int vi) {
    for (int i = 0; i < g_sel_n; i++)
        if (g_sel[i] == vi) return true;
    return false;
}
static void sel_add(int vi) {
    if (g_sel_n < SEL_MAX && !sel_contains(vi)) g_sel[g_sel_n++] = vi;
}
static void sel_remove(int vi) {
    for (int i = 0; i < g_sel_n; i++)
        if (g_sel[i] == vi) {
            for (int j = i; j + 1 < g_sel_n; j++) g_sel[j] = g_sel[j + 1];
            g_sel_n--;
            return;
        }
}
// The paths of the whole selection, in view order. Caller frees with
// sel_paths_free(). With no stored set it falls back to the row the menu
// was opened on, so exactly one resolver decides what "the selection"
// means for every command.
static DirEntry* ctx_target(void);
static char** sel_paths(int* out_count) {
    *out_count = 0;
    if (g_sel_n <= 0) {
        // No stored set (a menu opened straight from the keyboard): the
        // right-clicked target IS the selection - one resolver for every
        // command, so no action can silently act on nothing.
        DirEntry* t = ctx_target();
        if (!t) return NULL;
        char** one = (char**)calloc(1, sizeof(char*));
        if (!one) return NULL;
        one[0] = _strdup(t->path);
        if (!one[0]) { free(one); return NULL; }
        *out_count = 1;
        return one;
    }
    char** p = (char**)calloc((size_t)g_sel_n, sizeof(char*));
    if (!p) return NULL;
    for (int i = 0; i < g_sel_n; i++) {
        int vi = g_sel[i];
        if (vi < 0 || (size_t)vi >= g_app.view_count) continue;
        int ei = g_app.view[vi];
        if (ei < 0 || (size_t)ei >= g_app.count) continue;
        p[(*out_count)++] = _strdup(g_app.entries[ei].path);
    }
    return p;
}
static void sel_paths_free(char** p, int n) {
    if (!p) return;
    for (int i = 0; i < n; i++) free(p[i]);
    free(p);
}

static void pane_free(Pane* p);

// ------------------------------------------------------------
// WORKSPACES (top-level tabs)
// One tab in the toolbar IS one workspace: its own pane tree, its own
// active pane, and through the leaves its own folders / history /
// scroll / selection. g_ws[] is the single source of truth for tab
// state (the old g_app.tab_paths[] copy and the per-pane copy in
// FolderView are gone). While a workspace is live, g_pane_root /
// g_active_pane point INTO it and are the authoritative values; the
// stored root/active of other workspaces stay untouched because only
// the current workspace ever mutates. Tab labels are DERIVED from the
// active pane's path (ws_path), so there is no second copy to go stale.
// ------------------------------------------------------------
#define WS_NAME_MAX 64
typedef struct {
    Pane* root;               // layout tree (one leaf when freshly made)
    Pane* active;             // active leaf (always inside root)
    // The user's own tab label (Rename Tab / double-click the tab).  Empty
    // = automatic: the label follows the folder as before (ws_title).
    char name[WS_NAME_MAX];
} Workspace;

static Workspace g_ws[TAB_MAX];
static int g_ws_n = 0;
static int g_ws_cur = 0;
static int g_ws_last = -1;          // previously shown workspace (flip target
                                    // when the CURRENT tab is dragged)

// ------------------------------------------------------------
// DRAG SOURCES (spec: one explicit source per gesture, never shared)
// TAB_DRAG  - a TOP TAB  -> may absorb/split or reorder
// PANE_DRAG - a pane title strip -> may MOVE a pane into a drop zone
// RESIZE_DRAG - a divider's 3-dot handle -> may only change a ratio
// FOLDER_DRAG - a row in the file area -> Explorer only, NEVER layout
// Only the flag belonging to the armed source is ever consulted by its
// gesture handler, and a folder row can never raise a layout flag.
// ------------------------------------------------------------
typedef enum {
    DRAG_NONE = 0,
    DRAG_TAB,      // g_tab_armed / g_tab_drag
    DRAG_PANE,     // g_drag_split_armed / g_drag_split
    DRAG_RESIZE,   // g_splitter_drag
    DRAG_FOLDER    // row press: nothing layout-related may start
} DragSource;
static DragSource g_drag_src = DRAG_NONE;

// Reordering drag state (press a tab, move >5px, drop on a slot).
static bool g_tab_armed = false;      // pressed on a tab, below threshold
static bool g_tab_drag = false;       // threshold passed: reordering now
static bool g_tab_flipped = false;    // dragged the CURRENT tab over content
                                      // -> view flipped, restore on cancel
static int g_tab_arm_x = 0, g_tab_arm_y = 0;
static int g_tab_drag_idx = 0;        // workspace being reordered
static int g_tab_drag_x = 0;          // live cursor x (ghost + slot preview)
static int g_tab_drag_off = 0;        // grab offset inside the tab
static int g_tab_scroll = 0;          // strip scroll (only when overflowing)

// Live accessors: for the current workspace the globals ARE the state.
static Pane* ws_root(int i) {
    if (i < 0 || i >= g_ws_n) return NULL;
    return (i == g_ws_cur) ? g_pane_root : g_ws[i].root;
}
static Pane* ws_active(int i) {
    if (i < 0 || i >= g_ws_n) return NULL;
    return (i == g_ws_cur) ? g_active_pane : g_ws[i].active;
}
// Tab icon + label source: the workspace's active pane folder.
static const char* ws_path(int i) {
    Pane* a = ws_active(i);
    if (!a || a->kind != PN_LEAF || !a->folder.current_path[0]) return "";
    return a->folder.current_path;
}
// Where a tab dropped at client x would land (insertion slot, 0..n).
static int tab_slot_at(const Layout* L, int x) {
    int slot = 0;
    for (int i = 0; i < L->tab_drawn; i++) {
        const RectI* r = &L->tab_rects[i];
        if (x > r->x + r->w / 2) slot = i + 1;
    }
    return slot;
}

// Is (x, y) on the TOP TAB strip itself? Input (the tab drag) and drawing
// (the reorder insertion bar + ghost) share this one test, so the reorder
// chrome can never be drawn while the cursor is over Explorer content -
// there the split drop zones take over instead (spec: zones appear only
// while dragging a top tab, and only over another view's area).
static bool tab_strip_pt(const Layout* L, int x, int y) {
    if (!L) return false;
    return y >= L->toolbar.y && y < L->toolbar.y + SC(TAB_H) &&
           x >= L->tabs_x && x <= L->tabs_x + L->tab_area;
}

// A tab's CLICKABLE COLUMN: its drawn chip plus the invisible tab-bar
// padding above it (up to the window top). The chip is inset y1=SC(4)
// from the top edge; that thin strip is tab-bar territory, so a click
// there must select the TAB - never fall into the resize border
// (WM_NCHITTEST) or the drag strip. The GAPS between tabs and the area
// below the chips stay drag strip. Returns the tab index or -1.
static int tab_hit_at(const Layout* L, int x, int y) {
    if (!L || y < L->toolbar.y) return -1;
    for (int i = 0; i < L->tab_drawn; i++) {
        const RectI* r = &L->tab_rects[i];
        if (r->w > 0 && x >= r->x && x < r->x + r->w && y < r->y + r->h)
            return i;
    }
    return -1;
}

// ---- incremental type-to-select (Explorer-style type-ahead) -------------
// Typing a printable character while the file list has the keyboard starts
// (or EXTENDS) a case-insensitive filename prefix: every new character
// joins the previous ones and the highlight follows the whole prefix. A
// pause longer than TTS_TIMEOUT_MS, Escape, entering another folder and
// switching pane each start the NEXT sequence fresh.
//
// "Fresh" for the SELECTION follows WHO moved it, not the move itself:
// g_tts_sel remembers the row OUR OWN last run highlighted, so the match
// becoming selected can never eat the prefix that found it - while a
// selection made any other way (mouse click, arrows, Home/End,
// select-all, an empty click) means the next typed character starts a
// new search, exactly like Explorer.
#define TTS_TIMEOUT_MS  1000      // inactivity gap -> next char starts fresh
#define TTS_PREFIX_MAX  63        // typed characters kept in the prefix
static char  g_tts_prefix[TTS_PREFIX_MAX + 1];
static DWORD g_tts_last_ms;       // GetTickCount() of the last accepted char
static int   g_tts_sel = -1;      // the selection OUR last run produced

static void tts_reset(void) { g_tts_prefix[0] = '\0'; }
static bool tts_active(void) { return g_tts_prefix[0] != '\0'; }
static void tts_char(int ch, const Layout* L);   // used by the wheel key

// Every printable character THIS frame delivered, oldest first (up to
// cap).  The live pump fills charq - after a stall one frame can hold a
// whole typed word and a single latch would drop all but its last
// letter - while a plain one-character frame, and every selftest
// InputState (which never sets the queue), is char_pressed alone.
static int tts_frame_chars(const InputState* in, unsigned int* out, int cap) {
    int n = in->charq_n;
    if (n <= 0) {
        if (!in->char_pressed) return 0;
        out[0] = in->char_pressed;
        return 1;
    }
    if (n > cap) n = cap;
    for (int i = 0; i < n; i++) out[i] = in->charq[i];
    return n;
}

// ---- async thumbnail pipeline (worker thread + disk cache) ------------
// paint() may only QUEUE thumbnail/OLE work: one background thread does
// the slow shell calls and writes the result to the memory cache AND to
// %LOCALAPPDATA%\NovaFile\cache, so a picture is decoded exactly once
// ever. "Zoom in Downloads = the whole app freezes" was paint() calling
// IThumbnailProvider synchronously on the UI thread.
// g_tc_ui_shell counts slow lookups run OFF the worker thread: paint()
// must add 0 to it (asserted by the selftest).
static long g_tc_ui_shell = 0;
static __thread bool g_tc_on_worker = false;
static void tc_init(void);
static void tc_shutdown(void);
static void tc_drain(void);
