// List content zoom: Ctrl+wheel, the popup buttons or the bottom slider.
// g_zoom is what the layout uses and it EASES towards g_zoom_target every
// frame, so growing/shrinking the icons is smooth instead of jumpy.
static float g_zoom = 0.6f;
static float g_zoom_target = 0.6f;
// While the animated zoom is still easing, the cell and thumb sizes change
// EVERY frame: asking the shell for thumbnails now would mint a fresh cache
// key (and a slow fetch) per frame - the grid visibly "runs" while the
// animation crawls. Type icons are size independent and draw instead;
// thumbnails return the moment the size has settled.
static bool zoom_settling(void) {
    float d = g_zoom_target - g_zoom;
    if (d < 0.0f) d = -d;
    return d > 0.001f;
}
static bool g_size_drag = false;      // mouse held on the vertical zoom track
// Internally the zoom factor still runs to 3.0 (= the old 300%), but it is
// SHOWN as z/3: the slider ends at 100%, and 100% is as big as 300% used
// to be ("large icon" size).
#define ZOOM_MIN 0.45f                // displayed 15%
#define ZOOM_MAX 3.0f                 // displayed 100%

static float quantize_zoom(float z) {              // 5% steps on the DISPLAY
    z = (float)((int)(z * 6.6666667f + 0.5f)) * 0.15f;
    if (z < ZOOM_MIN) z = ZOOM_MIN;
    if (z > ZOOM_MAX) z = ZOOM_MAX;
    return z;
}

static int zoom_percent(float z) {                 // what the label shows
    float d = z / 3.0f * 100.0f + 0.5f;
    if (d > 100.0f) d = 100.0f;
    if (d < 0.0f) d = 0.0f;
    return (int)d;
}

// Transient status text (shown in the count slot of the status bar) and the
// frame until which the vertical zoom popup stays open after a zoom change.
static unsigned long g_status_until = 0;
// Deadlines are WALL-CLOCK ticks, not frame numbers: the loop now idles
// at a few frames a second, so "240 frames" would have kept a 4-second
// message (or the zoom popup) on screen for minutes.  0 = expired.
static bool tick_before(unsigned long until) {
    return until != 0 && (long)(until - (unsigned long)GetTickCount()) > 0;
}
static unsigned long tick_in(unsigned long ms) {
    unsigned long t = (unsigned long)GetTickCount() + ms;
    return t ? t : 1;
}
static unsigned long g_zoom_pop_until = 0;

